/**
 * IE-3c PART A, INC-1295 — THE MAP IS PART OF THE BUILD.
 *
 * The usage maps are generated by the build and never committed (scripts/i18n-usage-map.ts):
 * the client build emits `/i18n-usage.json`, and two lanes that add keys never conflict on them.
 *
 *   bun run scripts/i18n-map-guard.ts <copy>…  — each copy a build wrote (CI's `i18n-usage-map`
 *     job: `dist/client/i18n-usage.json` and the docs copy) must equal a fresh generation byte
 *     for byte; a missing or different copy fails.
 *   bun run i18n:map-guard (no copy)           — `e2e:local` runs it FIRST, before its build: the
 *     generator must answer a map that holds keys, so a broken generator fails before the suite
 *     spends seven minutes. The build that follows writes the copies.
 */
import { existsSync, readFileSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { errorText } from "../src/lib/error-text";
import { nonEmptyUsageMap } from "./i18n-usage-map";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");

/** Each copy that is missing or differs from `fresh`, with why; empty when all agree. */
export function staleCopies(copies: string[], fresh: string, root = ROOT): string[] {
  const out: string[] = [];
  for (const copy of copies) {
    const path = resolve(root, copy);
    const name = relative(root, path);
    if (!existsSync(path)) out.push(`${name}: missing (the build writes it)`);
    else if (readFileSync(path, "utf8") !== fresh)
      out.push(`${name}: differs from a fresh generation`);
  }
  return out;
}

function main(copies: string[]): number {
  let fresh: string;
  try {
    const map = nonEmptyUsageMap(ROOT);
    fresh = map.json;
    console.log(`[i18n:map-guard] the generator answers ${map.keyCount} keys.`);
  } catch (error) {
    console.error(`[i18n:map-guard] the usage map generator failed: ${errorText(error)}`);
    return 1;
  }
  if (copies.length === 0) {
    console.log("[i18n:map-guard] no copy named: the build writes the maps.");
    return 0;
  }
  const stale = staleCopies(copies, fresh);
  if (stale.length > 0) {
    console.error(
      "[i18n:map-guard] the build's usage map does not match the tree:\n" +
        stale.map((line) => `  - ${line}`).join("\n"),
    );
    return 1;
  }
  console.log(`[i18n:map-guard] the build's copies match the tree: ${copies.join(", ")}`);
  return 0;
}

if (import.meta.main) process.exit(main(process.argv.slice(2)));
